import { Mode8AiAction } from "./mode8WorkBlocks";
import {
  CopilotConversationSession,
  DEFAULT_SESSION_ID,
  deriveConversationTitle,
  idbDeleteSession,
  idbGetActiveSessionId,
  idbGetSession,
  idbListSessions,
  idbSaveSession,
  idbSetActiveSessionId,
} from "./chatHistoryIndexedDb";

export interface LlmChatMessage {
  id: string;
  role: "user" | "assistant" | "system";
  content: string;
  codeSnippet?: string;
  mode8Actions?: Mode8AiAction[];
  mode8Applied?: boolean;
  engineUsed?: string;
  isErrorNotice?: boolean;
  emotionalReward?: string;
  timestamp: string;
  createdAtMs?: number;
}

const STORAGE_KEY = "wxdiv_ai_chat_history_v1";
const ACTIVE_SESSION_STORAGE_KEY = "wxdiv_ai_active_session_v1";
const WARM_LOCAL_CACHE_LIMIT = 60;

export const POSITIVE_REINFORCEMENTS = [
  "¡Vas súper bien! Cada paso que das hoy hace crecer tu proyecto con mucha fuerza.",
  "¡Qué gran actitud! Todo código tiene solución y juntos lo podemos reparar con total calma.",
  "¡Excelente avance! Estás construyendo algo verdaderamente genial paso a paso.",
  "¡Ánimo, lo estás haciendo de maravilla! Equivocarse es parte natural de crear y aquí lo resolvemos juntos.",
  "¡Qué orgullo ver tu constancia y cuidado en cada detalle! Tómate un respiro cuando lo necesites.",
];

export function pickPositiveReinforcement(seed?: string): string {
  if (!seed) {
    return POSITIVE_REINFORCEMENTS[Math.floor(Math.random() * POSITIVE_REINFORCEMENTS.length)];
  }
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  }
  return POSITIVE_REINFORCEMENTS[hash % POSITIVE_REINFORCEMENTS.length];
}

export function createInitialWellnessGreeting(activeTab?: string): LlmChatMessage {
  const areaText =
    activeTab === "mode8"
      ? "tu mundo 3D y tu código DIV"
      : "tus juegos, apps y páginas web en DIV";

  return {
    id: "welcome",
    role: "assistant",
    content: `¡Hola! ¡Qué enorme alegría saludarte y acompañarte hoy! Estoy entusiasmado por trabajar contigo en ${areaText}.\n\nRecuerda siempre esto: ¡vas muy bien! Cada idea que pruebas tiene muchísimo valor y cualquier error se puede reparar paso a paso con calma. Puedes escribirme o hablarme con el micrófono para crear código, reparar fallos o charlar mientras construimos.\n\nPara arrancar con la mejor energía: ¿cómo te sientes en esta sesión actual?`,
    engineUsed: "Acompañamiento AURA LLM",
    timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    createdAtMs: Date.now(),
  };
}

let cachedMessages: LlmChatMessage[] | null = null;
let activeSessionId: string = DEFAULT_SESSION_ID;
let activeSessionCreatedAt: number = Date.now();
let activeSessionTab: string | undefined;
let savedSessions: CopilotConversationSession[] = [];
let hasHydratedFromIdb = false;
let hydrationPromise: Promise<LlmChatMessage[]> | null = null;
let persistQueue: Promise<void> = Promise.resolve();

const listeners = new Set<() => void>();

function notifyListeners() {
  listeners.forEach((fn) => fn());
}

function loadActiveSessionIdFromLocal(): string {
  if (typeof window === "undefined" || !window.localStorage) return DEFAULT_SESSION_ID;
  try {
    return localStorage.getItem(ACTIVE_SESSION_STORAGE_KEY) || DEFAULT_SESSION_ID;
  } catch {
    return DEFAULT_SESSION_ID;
  }
}

function persistActiveSessionIdToLocal(sessionId: string) {
  if (typeof window === "undefined" || !window.localStorage) return;
  try {
    localStorage.setItem(ACTIVE_SESSION_STORAGE_KEY, sessionId);
  } catch {
    // Ignore storage issues
  }
}

function loadFromLocalCache(activeTab?: string): LlmChatMessage[] {
  if (typeof window === "undefined" || !window.localStorage) {
    return [createInitialWellnessGreeting(activeTab)];
  }
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [createInitialWellnessGreeting(activeTab)];
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && parsed.length > 0) {
      return parsed;
    }
  } catch {
    // Ignore storage read issues
  }
  return [createInitialWellnessGreeting(activeTab)];
}

function persistToLocalCache(msgs: LlmChatMessage[]) {
  if (typeof window === "undefined" || !window.localStorage) return;
  try {
    // localStorage keeps a recent warm-start slice; IndexedDB stores the full unbounded history
    const recent = msgs.slice(-WARM_LOCAL_CACHE_LIMIT);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(recent));
  } catch {
    // Ignore storage quota issues
  }
}

function mergeMessagesPreservingOrder(
  persisted: LlmChatMessage[],
  inMemory: LlmChatMessage[]
): LlmChatMessage[] {
  if (persisted.length === 0) return [...inMemory];
  const seenIds = new Set(persisted.map((m) => m.id));
  const extraInMemory = inMemory.filter(
    (m) => m.id !== "welcome" && !seenIds.has(m.id)
  );
  return [...persisted, ...extraInMemory];
}

function enqueueIdbPersist(
  sessionId: string,
  messages: LlmChatMessage[],
  createdAt: number,
  tab?: string
): Promise<void> {
  const snapshot: CopilotConversationSession = {
    id: sessionId,
    title: deriveConversationTitle(messages),
    createdAt,
    updatedAt: Date.now(),
    activeTab: tab,
    messages: [...messages],
  };

  // Update in-memory session index immediately for instant UI responsiveness
  const existingIdx = savedSessions.findIndex((s) => s.id === sessionId);
  if (existingIdx >= 0) {
    savedSessions = [
      snapshot,
      ...savedSessions.filter((s) => s.id !== sessionId),
    ];
  } else {
    savedSessions = [snapshot, ...savedSessions];
  }

  persistQueue = persistQueue
    .then(async () => {
      await idbSaveSession(snapshot);
      await idbSetActiveSessionId(sessionId);
    })
    .catch(() => {
      // Non-fatal if IndexedDB unavailable
    });

  return persistQueue;
}

/**
 * Hydrates the full conversation history and archived sessions from IndexedDB on load/reload.
 */
export async function hydrateConversationHistoryFromIndexedDb(
  activeTab?: string
): Promise<LlmChatMessage[]> {
  if (hydrationPromise) {
    return hydrationPromise;
  }

  if (activeTab) {
    activeSessionTab = activeTab;
  }

  hydrationPromise = (async () => {
    try {
      const storedSessionId = await idbGetActiveSessionId();
      const targetId = storedSessionId || loadActiveSessionIdFromLocal() || DEFAULT_SESSION_ID;
      const existingSession = await idbGetSession(targetId);
      const allSessions = await idbListSessions();

      if (allSessions.length > 0) {
        savedSessions = allSessions;
      }

      if (existingSession && Array.isArray(existingSession.messages) && existingSession.messages.length > 0) {
        activeSessionId = existingSession.id;
        activeSessionCreatedAt = existingSession.createdAt || Date.now();
        activeSessionTab = existingSession.activeTab || activeSessionTab;
        const currentInMemory = cachedMessages || [];
        const merged = mergeMessagesPreservingOrder(
          existingSession.messages,
          currentInMemory
        );
        cachedMessages = merged;
        persistActiveSessionIdToLocal(activeSessionId);
        persistToLocalCache(merged);
        if (merged.length > existingSession.messages.length) {
          await enqueueIdbPersist(
            activeSessionId,
            merged,
            activeSessionCreatedAt,
            activeSessionTab
          );
        }
      } else {
        // Migrate existing warm localStorage history or initial greeting into IndexedDB
        activeSessionId = targetId;
        activeSessionCreatedAt = Date.now();
        const seedMessages = cachedMessages || loadFromLocalCache(activeSessionTab);
        cachedMessages = seedMessages;
        persistActiveSessionIdToLocal(activeSessionId);
        await enqueueIdbPersist(
          activeSessionId,
          seedMessages,
          activeSessionCreatedAt,
          activeSessionTab
        );
        const refreshed = await idbListSessions();
        if (refreshed.length > 0) savedSessions = refreshed;
      }
    } catch {
      if (!cachedMessages) {
        cachedMessages = loadFromLocalCache(activeSessionTab);
      }
    } finally {
      hasHydratedFromIdb = true;
      notifyListeners();
    }

    return cachedMessages || [createInitialWellnessGreeting(activeSessionTab)];
  })();

  return hydrationPromise;
}

export function getConversationMessages(activeTab?: string): LlmChatMessage[] {
  if (activeTab) activeSessionTab = activeTab;
  if (!cachedMessages) {
    activeSessionId = loadActiveSessionIdFromLocal();
    cachedMessages = loadFromLocalCache(activeTab);
  }
  if (!hasHydratedFromIdb && !hydrationPromise) {
    void hydrateConversationHistoryFromIndexedDb(activeTab);
  }
  return cachedMessages;
}

export function setConversationMessages(
  updater: LlmChatMessage[] | ((prev: LlmChatMessage[]) => LlmChatMessage[])
): LlmChatMessage[] {
  const prev = getConversationMessages();
  const next = typeof updater === "function" ? updater(prev) : updater;
  cachedMessages = [...next];
  persistToLocalCache(cachedMessages);
  void enqueueIdbPersist(
    activeSessionId,
    cachedMessages,
    activeSessionCreatedAt,
    activeSessionTab
  );
  notifyListeners();
  return cachedMessages;
}

/**
 * Starts a fresh active conversation while archiving the current conversation in IndexedDB
 * (whenever it contains user interactions) so prior chats remain accessible in the history panel.
 */
export function resetConversationMessages(activeTab?: string): LlmChatMessage[] {
  const prev = cachedMessages || [];
  const hasUserMessages = prev.some((m) => m.role === "user");
  if (hasUserMessages) {
    void enqueueIdbPersist(
      activeSessionId,
      prev,
      activeSessionCreatedAt,
      activeSessionTab
    );
  }

  const nextId = `session_${Date.now()}`;
  const now = Date.now();
  activeSessionId = nextId;
  activeSessionCreatedAt = now;
  if (activeTab) activeSessionTab = activeTab;

  const fresh = [createInitialWellnessGreeting(activeTab)];
  cachedMessages = fresh;
  persistActiveSessionIdToLocal(nextId);
  persistToLocalCache(fresh);
  void enqueueIdbPersist(nextId, fresh, now, activeSessionTab);
  notifyListeners();
  return fresh;
}

export async function switchConversationSession(
  sessionId: string
): Promise<LlmChatMessage[]> {
  const target =
    (await idbGetSession(sessionId)) ||
    savedSessions.find((s) => s.id === sessionId) ||
    null;
  if (!target) return getConversationMessages();

  activeSessionId = target.id;
  activeSessionCreatedAt = target.createdAt || Date.now();
  activeSessionTab = target.activeTab;
  cachedMessages = [...target.messages];
  persistActiveSessionIdToLocal(target.id);
  persistToLocalCache(cachedMessages);
  await idbSetActiveSessionId(target.id);
  notifyListeners();
  return cachedMessages;
}

export async function deleteConversationSession(sessionId: string): Promise<void> {
  await idbDeleteSession(sessionId);
  savedSessions = savedSessions.filter((s) => s.id !== sessionId);
  if (sessionId === activeSessionId) {
    if (savedSessions.length > 0) {
      await switchConversationSession(savedSessions[0].id);
      return;
    }
    resetConversationMessages(activeSessionTab);
    return;
  }
  notifyListeners();
}

export function getSavedConversationSessions(): CopilotConversationSession[] {
  return savedSessions;
}

export function getActiveSessionId(): string {
  return activeSessionId;
}

export function isHistoryHydrated(): boolean {
  return hasHydratedFromIdb;
}

export function flushConversationPersistence(): Promise<void> {
  return persistQueue;
}

/**
 * Resets only in-memory cache (for unit tests simulating an app reload from IndexedDB).
 */
export function resetConversationMemoryCacheForReload(): void {
  cachedMessages = null;
  savedSessions = [];
  hasHydratedFromIdb = false;
  hydrationPromise = null;
  persistQueue = Promise.resolve();
}

export function subscribeConversationMessages(listener: () => void): () => void {
  listeners.add(listener);
  if (!hasHydratedFromIdb && !hydrationPromise) {
    void hydrateConversationHistoryFromIndexedDb();
  }
  return () => listeners.delete(listener);
}

/**
 * Formats chat history for LLM multi-turn APIs (Gemini / WebLLM),
 * keeping recent turns and preserving conversational continuity.
 */
export function buildLlmHistoryPayload(
  messages: LlmChatMessage[],
  maxTurns: number = 14
): Array<{ role: "user" | "assistant"; content: string }> {
  return messages
    .filter((m) => (m.role === "user" || m.role === "assistant") && !m.isErrorNotice)
    .slice(-maxTurns)
    .map((m) => ({
      role: m.role as "user" | "assistant",
      content: m.codeSnippet ? `${m.content}\n\`\`\`div\n${m.codeSnippet}\n\`\`\`` : m.content,
    }));
}
