function normalizeGeminiHistory(rawHistory: any): Array<{ role: "user" | "model"; parts: Array<{ text: string }> }> {
  if (!Array.isArray(rawHistory)) return [];
  const cleaned: Array<{ role: "user" | "model"; parts: Array<{ text: string }> }> = [];
  for (const item of rawHistory.slice(-16)) {
    if (!item || typeof item.content !== "string") continue;
    const text = item.content.trim();
    if (!text) continue;
    const role: "user" | "model" = item.role === "user" ? "user" : "model";
    // Gemini chat history should alternate cleanly or merge consecutive same-role turns
    const prev = cleaned[cleaned.length - 1];
    if (prev && prev.role === role) {
      prev.parts[0].text += `\n\n${text}`;
    } else {
      cleaned.push({ role, parts: [{ text }] });
    }
  }
  // Chat history passed to ai.chats.create should start with a user turn if present, or be empty
  while (cleaned.length > 0 && cleaned[0].role !== "user") {
    cleaned.shift();
  }
  return cleaned;
}

function buildAssistTurnMessage(payload: {
  prompt: string;
  code: string;
  task: string;
  diagnostics?: Array<{ line?: number; message?: string; severity?: string; rule?: string }>;
  activeTab?: string;
  mode8Context?: any;
  currentFpg?: any[];
  sessionDurationMinutes?: number;
}): string {
  const parts: string[] = [];
  parts.push(`Mensaje del usuario: ${payload.prompt}`);
  const mins = Number.isFinite(payload.sessionDurationMinutes)
    ? Math.max(0, Math.floor(Number(payload.sessionDurationMinutes)))
    : 0;
  parts.push(
    `Intención detectada: ${payload.task}${
      payload.activeTab ? ` | Pestaña activa: ${payload.activeTab}` : ""
    } | Tiempo activo en sesión ininterrumpida: ${mins} min${
      mins > 30
        ? " (más de 30 min seguidos: incluye con calidez y refuerzo positivo una sugerencia sutil de breve descanso físico o estiramiento guiado)"
        : ""
    }`
  );

  if (Array.isArray(payload.diagnostics) && payload.diagnostics.length > 0) {
    const diagText = payload.diagnostics
      .slice(0, 12)
      .map((d) => `- Línea ${d.line ?? "?"} [${d.severity ?? "error"}]: ${d.message ?? "Error de sintaxis"}`)
      .join("\n");
    parts.push(`Diagnósticos actuales del compilador DIV:\n${diagText}`);
  }

  if (payload.mode8Context && payload.activeTab === "mode8") {
    parts.push(`Contexto del mapa 3D Modo 8: ${JSON.stringify(payload.mode8Context)}`);
  }

  if (Array.isArray(payload.currentFpg) && payload.currentFpg.length > 0) {
    parts.push(`Sprites en FPG actual: ${JSON.stringify(payload.currentFpg.slice(0, 24))}`);
  }

  if (payload.code && payload.code.trim()) {
    parts.push(`Código DIV actual en el editor:\n\`\`\`div\n${payload.code.slice(0, 8000)}\n\`\`\``);
  } else {
    parts.push("Nota: El editor de código DIV está vacío actualmente.");
  }

  return parts.join("\n\n");
}

// Procedural pixel-art fallback for retro sprite generation
function generateProceduralSpriteFallback(prompt: string, size: number, name: string) {
  const p = prompt.toLowerCase();
  let baseColor = "#38bdf8";
  let detailColor = "#f59e0b";

  if (p.includes("nave") || p.includes("ship")) {
    baseColor = "#06b6d4";
    detailColor = "#f43f5e";
  } else if (p.includes("alien") || p.includes("enemigo")) {
    baseColor = "#a855f7";
    detailColor = "#22c55e";
  } else if (p.includes("corazon") || p.includes("vida") || p.includes("heart")) {
    baseColor = "#ef4444";
    detailColor = "#fca5a5";
  } else if (p.includes("moneda") || p.includes("coin") || p.includes("oro")) {
    baseColor = "#eab308";
    detailColor = "#fef08a";
  }

  const palette = ["#00000000", baseColor, detailColor, "#ffffff"];
  const pixels: number[][] = [];

  for (let y = 0; y < size; y++) {
    const row: number[] = [];
    for (let x = 0; x < size; x++) {
      const cx = (size - 1) / 2;
      const cy = (size - 1) / 2;
      const dist = Math.hypot(x - cx, y - cy);
      if (dist < size * 0.4) {
        row.push((x + y) % 3 === 0 ? 2 : 1);
      } else {
        row.push(0);
      }
    }
    pixels.push(row);
  }

  return {
    name: name || "sprite",
    width: size,
    height: size,
    palette,
    pixels,
  };
}

