// Verify Gemini API connection with server environment key or header key
app.post("/api/gemini/verify", async (req, res) => {
  const { apiKey = "", model = "gemini-4-hydrogen" } = req.body || {};
  const headerKey = req.headers["x-api-key"] as string | undefined;
  const effectiveKey = (apiKey && apiKey.trim()) || headerKey;
  const ai = resolveAI(effectiveKey);

  if (!ai) {
    return res.status(400).json({
      success: false,
      code: "NO_API_KEY",
      message: "No existe una GEMINI_API_KEY configurada en el servidor.",
    });
  }

  try {
    const modelsToTry = Array.from(
      new Set([model || "gemini-4-hydrogen", "gemini-4-hydrogen", "gemini-3.1-flash-lite"])
    );
    const result = await generateGeminiWithFallback(ai, {
      contents: "Responde únicamente: OK DIV ENGINE",
      models: modelsToTry,
    });

    res.json({
      success: true,
      message: "¡Conexión validada exitosamente con Gemini API!",
      text: result.text || "OK",
      modelUsed: result.modelUsed,
    });
  } catch (err: any) {
    console.warn("Gemini verification failed:", err?.message || err);
    res.status(503).json({
      success: false,
      code: "UPSTREAM_ERROR",
      message: err?.message || "Error al validar la conexión con Google Gemini API",
    });
  }
});

// DIV Games Studio Real Multi-Turn LLM Assistant (JSON endpoint)
app.post("/api/gemini/assist", async (req, res) => {
  const {
    prompt = "",
    code = "",
    task = "chat",
    diagnostics = [],
    history = [],
    activeTab = "",
    mode8Context = null,
    currentFpg = [],
    sessionDurationMinutes = 0,
    apiKey = "",
    model = "gemini-4-hydrogen",
  } = req.body || {};
  const safeSessionMinutes =
    typeof sessionDurationMinutes === "number" && Number.isFinite(sessionDurationMinutes)
      ? Math.max(0, Math.floor(sessionDurationMinutes))
      : 0;
  const headerKey = req.headers["x-api-key"] as string | undefined;
  const effectiveKey = (apiKey && apiKey.trim()) || headerKey;
  const ai = resolveAI(effectiveKey);

  if (!ai) {
    return res.status(400).json({
      error: true,
      code: "NO_API_KEY",
      message:
        "No se detectó una clave GEMINI_API_KEY configurada en el servidor. Puedes usar WebLLM o CPU Local en la barra superior mientras tanto.",
    });
  }

  const userMessage = buildAssistTurnMessage({
    prompt,
    code,
    task,
    diagnostics,
    activeTab,
    mode8Context,
    currentFpg,
    sessionDurationMinutes: safeSessionMinutes,
  });
  const normalizedHistory = normalizeGeminiHistory(history);
  const modelsToTry = Array.from(
    new Set([model || "gemini-4-hydrogen", "gemini-4-hydrogen", "gemini-3.1-flash-lite"])
  );

  let lastError: any = null;
  for (const candidateModel of modelsToTry) {
    try {
      const chat = ai.chats.create({
        model: candidateModel,
        history: normalizedHistory,
        config: {
          systemInstruction: WXDIV_SYSTEM_INSTRUCTION,
        },
      });
      const result = await chat.sendMessage({ message: userMessage });
      const rawText = result.text || "";
      const fencedMatch = rawText.match(/```(?:div|pascal|prg|mode8-actions)?\s*([\s\S]*?)```/i);
      const enhancedText = applyWellbeingResponseMiddleware(rawText, {
        seed: prompt,
        task,
        preserveCodeBlocks: true,
        sessionDurationMinutes: safeSessionMinutes,
        codeSnippet: fencedMatch?.[1]?.trim(),
        hasCodeSuggestion: Boolean(fencedMatch && fencedMatch[1]?.trim()),
      });
      return res.json({
        text: enhancedText,
        modelUsed: candidateModel,
      });
    } catch (error: any) {
      lastError = error;
      console.warn(`Gemini assist model ${candidateModel} error:`, error?.message || error);
    }
  }

  return res.status(503).json({
    error: true,
    code: "UPSTREAM_ERROR",
    message:
      lastError?.message ||
      "El modelo Gemini no pudo responder en este momento. Puedes reintentar o cambiar temporalmente a WebLLM / CPU Local.",
  });
});

// DIV Games Studio Real Multi-Turn LLM Assistant (SSE Streaming endpoint)
app.post("/api/gemini/assist-stream", async (req, res) => {
  const {
    prompt = "",
    code = "",
    task = "chat",
    diagnostics = [],
    history = [],
    activeTab = "",
    mode8Context = null,
    currentFpg = [],
    sessionDurationMinutes = 0,
    apiKey = "",
    model = "gemini-4-hydrogen",
  } = req.body || {};
  const safeSessionMinutes =
    typeof sessionDurationMinutes === "number" && Number.isFinite(sessionDurationMinutes)
      ? Math.max(0, Math.floor(sessionDurationMinutes))
      : 0;
  const headerKey = req.headers["x-api-key"] as string | undefined;
  const effectiveKey = (apiKey && apiKey.trim()) || headerKey;
  const ai = resolveAI(effectiveKey);

  if (!ai) {
    return res.status(400).json({
      error: true,
      code: "NO_API_KEY",
      message:
        "No se detectó una clave GEMINI_API_KEY configurada en el servidor. Puedes usar WebLLM o CPU Local en la barra superior mientras tanto.",
    });
  }

  res.setHeader("Content-Type", "text/event-stream; charset=utf-8");
  res.setHeader("Cache-Control", "no-cache, no-transform");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders?.();

  const userMessage = buildAssistTurnMessage({
    prompt,
    code,
    task,
    diagnostics,
    activeTab,
    mode8Context,
    currentFpg,
    sessionDurationMinutes: safeSessionMinutes,
  });
  const normalizedHistory = normalizeGeminiHistory(history);
  const modelsToTry = Array.from(
    new Set([model || "gemini-4-hydrogen", "gemini-4-hydrogen", "gemini-3.1-flash-lite"])
  );

  let lastError: any = null;
  let streamedAny = false;

  for (const candidateModel of modelsToTry) {
    try {
      const chat = ai.chats.create({
        model: candidateModel,
        history: normalizedHistory,
        config: {
          systemInstruction: WXDIV_SYSTEM_INSTRUCTION,
        },
      });
      const stream = await chat.sendMessageStream({ message: userMessage });
      let accumulatedRaw = "";
      let prefixBuffer = "";
      let prefixResolved = false;

      for await (const chunk of stream) {
        if (res.writableEnded) break;
        const delta = chunk.text || "";
        if (!delta) continue;
        accumulatedRaw += delta;

        if (!prefixResolved) {
          prefixBuffer += delta;
          if (prefixBuffer.length >= 48 || prefixBuffer.includes("\n")) {
            prefixResolved = true;
            const prefix = getMissingWellbeingPrefix(prefixBuffer, {
              seed: prompt,
              task,
              sessionDurationMinutes: safeSessionMinutes,
            });
            const initialChunk = prefix ? `${prefix}\n\n${prefixBuffer}` : prefixBuffer;
            streamedAny = true;
            res.write(`data: ${JSON.stringify({ chunk: initialChunk })}\n\n`);
          }
        } else {
          streamedAny = true;
          res.write(`data: ${JSON.stringify({ chunk: delta })}\n\n`);
        }
      }

      if (!prefixResolved && prefixBuffer && !res.writableEnded) {
        const prefix = getMissingWellbeingPrefix(prefixBuffer, {
          seed: prompt,
          task,
          sessionDurationMinutes: safeSessionMinutes,
        });
        const initialChunk = prefix ? `${prefix}\n\n${prefixBuffer}` : prefixBuffer;
        streamedAny = true;
        res.write(`data: ${JSON.stringify({ chunk: initialChunk })}\n\n`);
      }

      if (!res.writableEnded) {
        const fencedMatch = accumulatedRaw.match(/```(?:div|pascal|prg|mode8-actions)?\s*([\s\S]*?)```/i);
        const suffix = getMissingWellbeingSuffix(accumulatedRaw, {
          seed: prompt,
          task,
          sessionDurationMinutes: safeSessionMinutes,
          codeSnippet: fencedMatch?.[1]?.trim(),
          hasCodeSuggestion: Boolean(fencedMatch && fencedMatch[1]?.trim()),
        });
        if (suffix) {
          res.write(`data: ${JSON.stringify({ chunk: `\n\n${suffix}` })}\n\n`);
        }
        res.write(`data: ${JSON.stringify({ done: true, modelUsed: candidateModel })}\n\n`);
        res.end();
      }
      return;
    } catch (error: any) {
      lastError = error;
      console.warn(`Gemini stream model ${candidateModel} error:`, error?.message || error);
      if (streamedAny) break;
    }
  }

  if (!res.writableEnded) {
    res.write(
      `data: ${JSON.stringify({
        error: true,
        code: "UPSTREAM_ERROR",
        message:
          lastError?.message ||
          "El modelo Gemini no pudo completar la respuesta en este momento.",
      })}\n\n`
    );
    res.end();
  }
});

// Sprite generation endpoint with Gemini AI
app.post("/api/gemini/generate-sprite", async (req, res) => {
  const { prompt = "", size = 16, name = "sprite", apiKey = "" } = req.body || {};
  const headerKey = req.headers["x-api-key"] as string | undefined;
  const effectiveKey = (apiKey && apiKey.trim()) || headerKey;
  const ai = resolveAI(effectiveKey);

  if (!ai) {
    return res.json(generateProceduralSpriteFallback(prompt, size, name));
  }

  const systemInstruction = `You are a retro pixel-art generator for DIV Games Studio (WXDIV 3.0).
Generate a pixel art grid of size ${size}x${size} based on the user's prompt.
Return ONLY a valid JSON object matching this schema:
{
  "name": "string",
  "width": ${size},
  "height": ${size},
  "palette": ["#00000000", "#112233", ...], // Array of hex color strings. First entry MUST be "#00000000" for transparent.
  "pixels": [[0, 1, 2, ...], ...] // 2D array of palette indices for each (y, x), where 0 is transparent.
}
Do not include markdown ticks or any extra text, only the raw JSON.`;

  try {
    const result = await generateGeminiWithFallback(ai, {
      contents: `Create pixel art for: ${prompt} (size: ${size}x${size}, name: ${name})`,
      models: ["gemini-4-hydrogen", "gemini-3.1-flash-lite"],
      config: {
        systemInstruction,
        responseMimeType: "application/json",
      },
    });

    const parsed = JSON.parse(result.text || "{}");
    if (!parsed.pixels || !parsed.palette) {
      throw new Error("Invalid sprite JSON structure");
    }
    res.json(parsed);
  } catch (error: any) {
    console.warn("Gemini sprite API error, providing procedural sprite fallback:", error?.message || error);
    res.json(generateProceduralSpriteFallback(prompt, size, name));
  }
});

