function escapeHtmlText(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

const BLOCKED_ROOT_ENTRIES = new Set([
  "src",
  "node_modules",
  "scripts",
  "dist",
  "dev-dist",
  "public",
  "server.ts",
  "package.json",
  "package-lock.json",
  "bun.lock",
  "tsconfig.json",
  "vite.config.ts",
  "metadata.json",
  "index.html",
  "index.htm",
]);

function safeResolveStaticPath(
  baseDir: string,
  reqPath: string,
  enforceRootBlocklist = false
): string | null {
  let decoded = reqPath;
  try {
    decoded = decodeURIComponent(reqPath);
  } catch {
    return null;
  }
  if (decoded.includes("\0")) return null;
  const normalized = decoded.replace(/\\/g, "/").replace(/^\/+/, "");
  const segments = normalized.split("/").filter(Boolean);
  if (segments.some((seg) => seg.startsWith(".") || seg === "..")) {
    return null;
  }
  if (enforceRootBlocklist && (segments.length === 0 || BLOCKED_ROOT_ENTRIES.has(segments[0]))) {
    return null;
  }
  const resolved = path.resolve(baseDir, normalized);
  const rootWithSep = baseDir.endsWith(path.sep) ? baseDir : baseDir + path.sep;
  if (resolved !== baseDir && !resolved.startsWith(rootWithSep)) {
    return null;
  }
  return resolved;
}

function renderStaticDirectoryIndex(dirPath: string, urlPath: string): string {
  const cleanUrlPath = urlPath.endsWith("/") ? urlPath : `${urlPath}/`;
  const entries = fs
    .readdirSync(dirPath, { withFileTypes: true })
    .filter((entry) => !entry.name.startsWith("."))
    .sort((a, b) => {
      if (a.isDirectory() !== b.isDirectory()) return a.isDirectory() ? -1 : 1;
      return a.name.localeCompare(b.name);
    });

  const itemsHtml = entries
    .map((entry) => {
      const suffix = entry.isDirectory() ? "/" : "";
      const href = encodeURI(`${cleanUrlPath}${entry.name}${suffix}`);
      const label = escapeHtmlText(`${entry.name}${suffix}`);
      const badge = entry.isDirectory() ? "Carpeta" : path.extname(entry.name).toLowerCase() || "Archivo";
      return `<li style="margin:6px 0;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 12px;border:1px solid #e2e8f0;border-radius:8px;background:#fff;">
        <a href="${href}" style="color:#7c2d48;font-weight:600;text-decoration:none;word-break:break-all;">${label}</a>
        <span style="font-size:12px;color:#64748b;font-family:monospace;">${escapeHtmlText(badge)}</span>
      </li>`;
    })
    .join("\n");

  const parentHref =
    cleanUrlPath !== "/"
      ? encodeURI(cleanUrlPath.replace(/[^/]+\/$/, "") || "/")
      : null;

  return `<!doctype html>
<html lang="es">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Índice de ${escapeHtmlText(cleanUrlPath)}</title>
  </head>
  <body style="margin:0;padding:24px;font-family:system-ui,-apple-system,sans-serif;background:#f8fafc;color:#0f172a;">
    <main style="max-width:720px;margin:0 auto;">
      <h1 style="font-size:18px;margin:0 0 6px;">Contenido de ${escapeHtmlText(cleanUrlPath)}</h1>
      <p style="font-size:13px;color:#475569;margin:0 0 16px;">Módulos y subcarpetas disponibles en el servidor.</p>
      ${
        parentHref
          ? `<div style="margin-bottom:12px;"><a href="${parentHref}" style="font-size:13px;color:#334155;text-decoration:none;font-weight:600;">← Subir nivel</a></div>`
          : ""
      }
      <ul style="list-style:none;padding:0;margin:0;">
        ${itemsHtml || `<li style="padding:12px;color:#64748b;font-size:13px;">Carpeta vacía</li>`}
      </ul>
    </main>
  </body>
</html>`;
}

interface StaticRootSpec {
  dir: string;
  enforceBlocklist?: boolean;
}

function createInternalFolderAndHtmlMiddleware(
  staticRoots: StaticRootSpec[],
  options?: { allowRoot?: boolean }
): express.RequestHandler {
  return (req, res, next) => {
    if (req.method !== "GET" && req.method !== "HEAD") return next();
    const reqPath = req.path || "/";
    if (
      reqPath.startsWith("/api/") ||
      reqPath.startsWith("/p/") ||
      reqPath.startsWith("/@") ||
      reqPath.startsWith("/src/") ||
      reqPath.startsWith("/node_modules/")
    ) {
      return next();
    }
    if (!options?.allowRoot && (reqPath === "/" || reqPath === "/index.html")) {
      return next();
    }

    for (const rootSpec of staticRoots) {
      const rootDir = rootSpec.dir;
      if (!fs.existsSync(rootDir)) continue;

      const resolved = safeResolveStaticPath(rootDir, reqPath, Boolean(rootSpec.enforceBlocklist));
      if (resolved && fs.existsSync(resolved)) {
        const stat = fs.statSync(resolved);
        if (stat.isDirectory()) {
          if (!reqPath.endsWith("/")) {
            const qs = req.url.includes("?") ? req.url.slice(req.url.indexOf("?")) : "";
            return res.redirect(302, `${reqPath}/${qs}`);
          }
          const idxHtml = path.join(resolved, "index.html");
          const idxHtm = path.join(resolved, "index.htm");
          if (fs.existsSync(idxHtml) && fs.statSync(idxHtml).isFile()) {
            res.setHeader("Cache-Control", "no-cache");
            return res.sendFile(idxHtml);
          }
          if (fs.existsSync(idxHtm) && fs.statSync(idxHtm).isFile()) {
            res.setHeader("Cache-Control", "no-cache");
            return res.sendFile(idxHtm);
          }
          if (reqPath !== "/") {
            res.setHeader("Content-Type", "text/html; charset=utf-8");
            res.setHeader("Cache-Control", "no-cache");
            return res.send(renderStaticDirectoryIndex(resolved, reqPath));
          }
        } else if (stat.isFile()) {
          if (/\.(html?|htm)$/i.test(resolved)) {
            res.setHeader("Cache-Control", "no-cache");
          }
          return res.sendFile(resolved);
        }
      }

      // Support extensionless calls to internal .html / .htm modules (e.g. /modulos/test -> /modulos/test.html)
      if (!path.extname(reqPath) && !reqPath.endsWith("/")) {
        for (const ext of [".html", ".htm"]) {
          const resolvedHtml = safeResolveStaticPath(
            rootDir,
            `${reqPath}${ext}`,
            Boolean(rootSpec.enforceBlocklist)
          );
          if (resolvedHtml && fs.existsSync(resolvedHtml) && fs.statSync(resolvedHtml).isFile()) {
            res.setHeader("Cache-Control", "no-cache");
            return res.sendFile(resolvedHtml);
          }
        }
      }
    }

    return next();
  };
}

// Vite middleware setup
async function startServer() {
  const httpServer = http.createServer(app);
  const publicPath = path.resolve(process.cwd(), "public");

  if (process.env.NODE_ENV !== "production") {
    if (process.env.DISABLE_HMR === "true") {
      app.get("/@vite/client", (_req, res) => {
        res.type("application/javascript");
        res.setHeader("Cache-Control", "no-store");
        res.send(`
const sheetsMap = new Map();
if ("document" in globalThis) {
  document.querySelectorAll("style[data-vite-dev-id]").forEach((el) => {
    sheetsMap.set(el.getAttribute("data-vite-dev-id"), el);
  });
}
let lastInsertedStyle;
export function updateStyle(id, content) {
  let style = sheetsMap.get(id);
  if (!style) {
    style = document.createElement("style");
    style.setAttribute("type", "text/css");
    style.setAttribute("data-vite-dev-id", id);
    style.textContent = content;
    if (!lastInsertedStyle) {
      document.head.appendChild(style);
      setTimeout(() => { lastInsertedStyle = undefined; }, 0);
    } else {
      lastInsertedStyle.insertAdjacentElement("afterend", style);
    }
    lastInsertedStyle = style;
  } else {
    style.textContent = content;
  }
  sheetsMap.set(id, style);
}
export function removeStyle(id) {
  const style = sheetsMap.get(id);
  if (style) {
    document.head.removeChild(style);
    sheetsMap.delete(id);
  }
}
export function createHotContext() {
  return {
    data: {},
    accept() {},
    acceptExports() {},
    dispose() {},
    prune() {},
    decline() {},
    invalidate() {},
    on() {},
    off() {},
    send() {},
  };
}
export function injectQuery(url, queryToInject) {
  if (url[0] !== "." && url[0] !== "/") return url;
  const pathname = url.replace(/[?#].*$/, "");
  const { search, hash } = new URL(url, "http://vite.dev");
  return pathname + "?" + queryToInject + (search ? "&" + search.slice(1) : "") + (hash || "");
}
export class ErrorOverlay extends HTMLElement {}
`);
      });
    }

    // Serve internal folders & .html test modules from public/ and safe root subdirectories before Vite SPA fallback
    app.use(
      createInternalFolderAndHtmlMiddleware(
        [{ dir: publicPath }, { dir: process.cwd(), enforceBlocklist: true }],
        { allowRoot: false }
      )
    );

    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        hmr:
          process.env.DISABLE_HMR === "true"
            ? false
            : { server: httpServer },
      },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const currentDir = typeof __dirname !== "undefined" ? __dirname : process.cwd();
    const distPath = fs.existsSync(path.join(process.cwd(), "dist", "index.html"))
      ? path.join(process.cwd(), "dist")
      : fs.existsSync(path.join(currentDir, "index.html"))
        ? currentDir
        : path.join(process.cwd(), "dist");
    const staticRootSpecs: StaticRootSpec[] = [
      { dir: distPath },
      ...(fs.existsSync(publicPath) && publicPath !== distPath ? [{ dir: publicPath }] : []),
      { dir: process.cwd(), enforceBlocklist: true },
    ];

    app.use(createInternalFolderAndHtmlMiddleware(staticRootSpecs, { allowRoot: true }));

    for (const rootDir of Array.from(new Set([distPath, ...(fs.existsSync(publicPath) ? [publicPath] : [])]))) {
      app.use(
        express.static(rootDir, {
          extensions: ["html", "htm"],
          index: ["index.html", "index.htm"],
        })
      );
    }

    app.get("*", (req, res) => {
      if (req.path.startsWith("/api/")) {
        return res.status(404).json({ error: "Endpoint no encontrado" });
      }
      // Do not mask missing internal .html files or static assets with the root SPA index.html
      if (path.extname(req.path)) {
        return res.status(404).type("text/plain; charset=utf-8").send("Archivo no encontrado");
      }
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  httpServer.listen(PORT, "0.0.0.0", () => {
    console.log(`WXDIV 3.0 Server running on http://localhost:${PORT}`);
  });
}

startServer();
