const SESSION_START_STORAGE_KEY = "wxdiv_session_started_at_v1";
const LAST_ACTIVITY_STORAGE_KEY = "wxdiv_last_activity_at_v1";
const UNINTERRUPTED_GAP_RESET_MS = 10 * 60 * 1000;
let memorySessionStartMs: number | null = null;
let memoryLastActivityMs: number | null = null;

/**
 * Retrieves or initializes the active uninterrupted development session start timestamp.
 */
export function getSessionStartTimestamp(nowMs: number = Date.now()): number {
  if (typeof window !== "undefined") {
    try {
      const existing = window.sessionStorage?.getItem(SESSION_START_STORAGE_KEY);
      if (existing) {
        const parsed = Number(existing);
        if (Number.isFinite(parsed) && parsed > 0 && parsed <= nowMs) {
          memorySessionStartMs = parsed;
          return parsed;
        }
      }
      window.sessionStorage?.setItem(SESSION_START_STORAGE_KEY, String(nowMs));
    } catch {
      // Ignore storage access errors in restricted iframes
    }
  }
  if (!memorySessionStartMs || memorySessionStartMs > nowMs) {
    memorySessionStartMs = nowMs;
  }
  return memorySessionStartMs;
}

export function setSessionStartTimestamp(timestampMs: number): void {
  if (!Number.isFinite(timestampMs) || timestampMs <= 0) return;
  memorySessionStartMs = timestampMs;
  memoryLastActivityMs = timestampMs;
  if (typeof window !== "undefined") {
    try {
      window.sessionStorage?.setItem(SESSION_START_STORAGE_KEY, String(timestampMs));
      window.sessionStorage?.setItem(LAST_ACTIVITY_STORAGE_KEY, String(timestampMs));
    } catch {
      // Ignore storage errors
    }
  }
}

/**
 * Records active user interaction; if there was a natural break (>=10 min idle gap),
 * resets the uninterrupted session timer cleanly.
 */
export function recordSessionActivity(nowMs: number = Date.now()): number {
  let prevActivity = memoryLastActivityMs;
  if (typeof window !== "undefined") {
    try {
      const raw = window.sessionStorage?.getItem(LAST_ACTIVITY_STORAGE_KEY);
      if (raw) {
        const parsed = Number(raw);
        if (Number.isFinite(parsed) && parsed > 0) prevActivity = parsed;
      }
    } catch {
      // Ignore storage errors
    }
  }

  if (prevActivity && nowMs - prevActivity >= UNINTERRUPTED_GAP_RESET_MS) {
    setSessionStartTimestamp(nowMs);
    return nowMs;
  }

  const start = getSessionStartTimestamp(nowMs);
  memoryLastActivityMs = nowMs;
  if (typeof window !== "undefined") {
    try {
      window.sessionStorage?.setItem(LAST_ACTIVITY_STORAGE_KEY, String(nowMs));
    } catch {
      // Ignore storage errors
    }
  }
  return start;
}

const COMPLETED_BREAKS_STORAGE_KEY = "wxdiv_completed_breaks_v1";
const RECOMMENDED_BREAK_INTERVAL_MIN = 25;
let memoryCompletedBreaks = 0;

export interface DeveloperHealthMetrics {
  sessionMinutes: number;
  recommendedBreaks: number;
  nextBreakInMinutes: number;
  breakDue: boolean;
  completedBreaks: number;
  statusLabel: "Ritmo saludable" | "Pausa próxima" | "Descanso recomendado";
}

export function getCompletedBreaksCount(): number {
  if (typeof window !== "undefined") {
    try {
      const raw = window.sessionStorage?.getItem(COMPLETED_BREAKS_STORAGE_KEY);
      if (raw !== null) {
        const parsed = Number(raw);
        if (Number.isFinite(parsed) && parsed >= 0) {
          memoryCompletedBreaks = Math.floor(parsed);
          return memoryCompletedBreaks;
        }
      }
    } catch {
      // Ignore storage errors
    }
  }
  return memoryCompletedBreaks;
}

export function recordCompletedBreak(): number {
  const next = getCompletedBreaksCount() + 1;
  memoryCompletedBreaks = next;
  if (typeof window !== "undefined") {
    try {
      window.sessionStorage?.setItem(COMPLETED_BREAKS_STORAGE_KEY, String(next));
    } catch {
      // Ignore storage errors
    }
  }
  return next;
}

/**
 * Resets the uninterrupted session counter when the user takes a physical break or stretch.
 */
export function markPhysicalBreakTaken(nowMs: number = Date.now()): number {
  setSessionStartTimestamp(nowMs);
  recordCompletedBreak();
  return 0;
}

export function getSessionDurationMinutes(
  sessionStartMs?: number,
  nowMs: number = Date.now()
): number {
  const start = sessionStartMs ?? getSessionStartTimestamp(nowMs);
  const diffMs = Math.max(0, nowMs - start);
  return Math.floor(diffMs / 60000);
}

export function getDeveloperHealthMetrics(
  sessionStartMs?: number,
  nowMs: number = Date.now()
): DeveloperHealthMetrics {
  const sessionMinutes = getSessionDurationMinutes(sessionStartMs, nowMs);
  const completedBreaks = getCompletedBreaksCount();
  const recommendedBreaks = Math.floor(sessionMinutes / RECOMMENDED_BREAK_INTERVAL_MIN);
  const breakDue = sessionMinutes >= RECOMMENDED_BREAK_INTERVAL_MIN;
  const remainder = sessionMinutes % RECOMMENDED_BREAK_INTERVAL_MIN;
  const nextBreakInMinutes = breakDue ? 0 : RECOMMENDED_BREAK_INTERVAL_MIN - remainder;

  let statusLabel: DeveloperHealthMetrics["statusLabel"] = "Ritmo saludable";
  if (sessionMinutes > 30 || breakDue) {
    statusLabel = "Descanso recomendado";
  } else if (sessionMinutes >= 20) {
    statusLabel = "Pausa próxima";
  }

  return {
    sessionMinutes,
    recommendedBreaks,
    nextBreakInMinutes,
    breakDue,
    completedBreaks,
    statusLabel,
  };
}

