function stableIndex(seed: string, length: number): number {
  if (!seed) return 0;
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  }
  return hash % length;
}

function extractFirstFencedBlock(text: string): string | undefined {
  const match = text.match(/```(?:div|pascal|prg|mode8-actions)?\s*([\s\S]*?)```/i);
  return match?.[1]?.trim() || undefined;
}

function extractCodeSubjectLabel(
  codeSnippet?: string,
  rewardSubject?: string,
  mode8Actions?: Mode8AiAction[]
): string {
  if (rewardSubject && rewardSubject.trim()) {
    return ` ("${rewardSubject.trim().slice(0, 40)}")`;
  }
  if (mode8Actions && mode8Actions.length > 0) {
    const first = mode8Actions[0];
    if (first.type === "add_model") return ` (modelo "${first.modelId}")`;
    if (first.type === "add_stairs") return " (escalera 3D)";
    if (first.type === "add_platform") return " (plataforma 3D)";
    if (first.type === "add_voxel") return ` (bloque "${first.voxelId}")`;
    if (first.type === "build_template") return ` (escena "${first.template}")`;
  }
  if (codeSnippet) {
    const progMatch = codeSnippet.match(/\bPROGRAM\s+([A-Za-z0-9_]+)/i);
    if (progMatch?.[1]) return ` (${progMatch[1]})`;
    const procMatch = codeSnippet.match(/\bPROCESS\s+([A-Za-z0-9_]+)/i);
    if (procMatch?.[1]) return ` (${procMatch[1]})`;
  }
  return "";
}

export function classifyCodeSuggestionContext(options: {
  task?: string;
  seed?: string;
  codeSnippet?: string;
  mode8Actions?: Mode8AiAction[];
  hasCodeSuggestion?: boolean;
}): CodeSuggestionContext {
  const seedNorm = (options.seed || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  const code = options.codeSnippet || "";

  if (options.task === "module") return "module";
  if (
    options.task === "fix" ||
    /\b(repar|correg|arregl|solucion|fix|debug|error|errores|sanead)\b/i.test(seedNorm)
  ) {
    return "repair";
  }
  if ((options.mode8Actions && options.mode8Actions.length > 0) || /\b(start_mode8|m8_set_doom_sector|m8_place_voxel|m8_add_model|c_m8)\b/i.test(code)) {
    return "mode8";
  }
  if (/\b(set_html5_mode|web_page|web_navbar|web_hero|web_pricing|web_feature|web_footer)\b/i.test(code)) {
    return "web";
  }
  if (/\b(draw_button|draw_input|draw_select|draw_table|draw_modal)\b/i.test(code)) {
    return "app";
  }
  if (options.hasCodeSuggestion || code.trim().length > 0 || options.task === "create") {
    return "game";
  }
  return "general";
}

/**
 * Generates a personalized, enthusiastic, and warm emotional reward message
 * tailored to the exact code suggestion, repair, or module just created.
 */
export function buildPersonalizedEmotionalReward(options: {
  seed?: string;
  task?: string;
  codeSnippet?: string;
  mode8Actions?: Mode8AiAction[];
  hasCodeSuggestion?: boolean;
  rewardSubject?: string;
}): string {
  const ctx = classifyCodeSuggestionContext(options);
  const seed = options.seed || options.codeSnippet || options.rewardSubject || "";

  if (ctx === "general") {
    return pickPositiveReinforcement(seed);
  }

  const pool = REWARD_TEMPLATES[ctx];
  const template = pool[stableIndex(`reward:${ctx}:${seed}`, pool.length)];
  const subjectPart = extractCodeSubjectLabel(
    options.codeSnippet,
    options.rewardSubject,
    options.mode8Actions
  );
  return `Recompensa emocional: ${template.replace("{subjectPart}", subjectPart)}`;
}

export function pickCordialGreeting(seed: string = ""): string {
  return CORDIAL_GREETINGS[stableIndex(`greet:${seed}`, CORDIAL_GREETINGS.length)];
}

export function pickMoodQuestion(seed: string = ""): string {
  return SESSION_MOOD_QUESTIONS[stableIndex(`mood:${seed}`, SESSION_MOOD_QUESTIONS.length)];
}

export function pickSessionMoodQuestion(seed: string = ""): string {
  return pickMoodQuestion(seed);
}

/**
 * Selects a dynamic wellness tip, brief mindful breathing exercise, or subtle
 * guided physical break / stretch tailored to the user's uninterrupted session duration.
 */
export function selectDynamicWellnessTip(
  sessionDurationMinutes: number = 0,
  seed: string = ""
): string {
  const safeMins = Number.isFinite(sessionDurationMinutes)
    ? Math.max(0, Math.floor(sessionDurationMinutes))
    : 0;

  let pool: string[];
  if (safeMins >= 60) {
    pool = LONG_SESSION_PAUSES;
  } else if (safeMins > 30) {
    pool = UNINTERRUPTED_30PLUS_STRETCHES;
  } else if (safeMins >= 15) {
    pool = FOCUS_SESSION_EXERCISES;
  } else {
    pool = EARLY_SESSION_TIPS;
  }

  const chosen = pool[stableIndex(`tip:${safeMins}:${seed}`, pool.length)];
  return chosen.replace(/\{mins\}/g, String(safeMins));
}

/**
 * Strips fenced code blocks so wellbeing checks evaluate natural-language prose only.
 */
function stripFencedBlocks(text: string): string {
  return (text || "").replace(/```[\s\S]*?```/g, " ").trim();
}

export function inspectWellbeingSignals(text: string): WellbeingCheckResult {
  const prose = stripFencedBlocks(text);
  const norm = prose
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  const hasGreeting =
    /^(¡?\s*(hola|buenos dias|buenas tardes|buenas noches|buenas|que gusto|que alegria|que enorme alegria|buen momento|saludos))/i.test(
      norm
    ) ||
    /\b(hola|que gusto saludarte|que alegria saludarte|que enorme alegria saludarte|me da mucho gusto|que alegria verte)\b/i.test(
      norm.slice(0, 180)
    );

  const hasEmotionalReward =
    /\b(recompensa emocional|lo logramos juntos|que ilusion ver|espectacular avance|increible impulso|que maravilla ver|fantastica decision|que emocion ver|bravo por|bravisimo por)\b/i.test(
      norm
    );

  const hasPositiveReinforcement =
    hasEmotionalReward ||
    /\b(vas muy bien|vas super bien|vas bien|todo se puede reparar|todo error se puede reparar|todo codigo tiene solucion|paso a paso|cada paso|excelente avance|buen trabajo|cada intento|equivocarse es parte natural|lo resolvemos juntos|lo arreglamos juntos|con calma|lo estas haciendo genial|lo estas haciendo de maravilla)\b/i.test(
      norm
    );

  const hasSessionMoodQuestion =
    /(?:¿|\b)(como te sientes|como te encuentras|como va tu animo|como va tu estado de animo|como sientes tu energia|como estas)[^.!?\n]*\b(sesion actual|esta sesion|tu sesion)\b[^.!?\n]*\?/i.test(
      norm
    );

  const hasMoodQuestion =
    hasSessionMoodQuestion ||
    /(?:¿|\b)(como estas|como te sientes|como te encuentras|como va tu estado de animo|como va tu animo|estado de animo|como sientes tu energia|como te sientes ahora|como vamos)\b[^.!?\n]*\?/i.test(
      norm
    ) ||
    /\b(como te sientes|como estas hoy|como va tu animo)\b/i.test(norm);

  const hasWellnessTipOrBreathing =
    /\b(tip de bienestar|respiracion consciente|pausa saludable|pausa breve|ejercicio breve de respiracion|estiramiento guiado|descanso fisico|sugerencia de descanso|inhala|exhala|sorbo de agua|aparta la vista|relaja los hombros|estira cuello|estira los brazos|estira tus munecas|suelta el teclado)\b/i.test(
      norm
    );

  return {
    hasGreeting,
    hasPositiveReinforcement,
    hasEmotionalReward,
    hasMoodQuestion,
    hasSessionMoodQuestion,
    hasWellnessTipOrBreathing,
  };
}

/**
 * Returns only the missing greeting prefix (if the response lacks a cordial greeting).
 */
export function getMissingWellbeingPrefix(
  text: string,
  options: WellbeingMiddlewareOptions = {}
): string {
  const { hasGreeting } = inspectWellbeingSignals(text);
  if (hasGreeting) return "";
  return pickCordialGreeting(options.seed || text);
}

/**
 * Returns only the missing personalized emotional reward / positive reinforcement,
 * genuine current-session mood question, and dynamic session wellness tip suffix.
 */
export function getMissingWellbeingSuffix(
  text: string,
  options: WellbeingMiddlewareOptions = {}
): string {
  const signals = inspectWellbeingSignals(text);
  const parts: string[] = [];
  const extractedCode = options.codeSnippet || extractFirstFencedBlock(text);
  const hasCode = Boolean(
    options.hasCodeSuggestion ||
      (extractedCode && extractedCode.trim().length > 0) ||
      (options.mode8Actions && options.mode8Actions.length > 0) ||
      options.task === "create" ||
      options.task === "fix" ||
      options.task === "module"
  );
  const seed = options.seed || text;

  if (hasCode) {
    if (!signals.hasEmotionalReward) {
      parts.push(
        buildPersonalizedEmotionalReward({
          seed,
          task: options.task,
          codeSnippet: extractedCode,
          mode8Actions: options.mode8Actions,
          hasCodeSuggestion: true,
          rewardSubject: options.rewardSubject,
        })
      );
    }
  } else if (!signals.hasPositiveReinforcement) {
    parts.push(pickPositiveReinforcement(seed));
  }

  if (!signals.hasWellnessTipOrBreathing) {
    const mins =
      typeof options.sessionDurationMinutes === "number"
        ? options.sessionDurationMinutes
        : getSessionDurationMinutes();
    parts.push(selectDynamicWellnessTip(mins, seed));
  }

  // Always conclude with a genuine question about how the user feels in their current session
  // (if neither started nor ended with one).
  if (!signals.hasSessionMoodQuestion) {
    parts.push(pickSessionMoodQuestion(seed));
  }

  return parts.join(" ");
}

/**
 * Core Wellbeing Chat Middleware:
 * Intercepts any AI/Copilot response (plain prose or mixed prose + ```div``` / ```mode8-actions``` blocks),
 * preserves technical content intact, and ensures:
 * 1) An enthusiastic, warm, empathetic greeting
 * 2) Personalized Emotional Reward on code/module suggestions (or positive reinforcement in chat)
 * 3) Dynamic wellness tip / guided stretch based on uninterrupted session duration (>30m stretch prompt)
 * 4) A genuine question about how the user feels in their current session
 */
export function applyWellbeingResponseMiddleware(
  rawResponse: string,
  options: WellbeingMiddlewareOptions = {}
): string {
  const original = (rawResponse || "").trim();
  const seed = options.seed || original;
  const sessionMinutes =
    typeof options.sessionDurationMinutes === "number"
      ? options.sessionDurationMinutes
      : getSessionDurationMinutes();

  if (!original) {
    const greeting = pickCordialGreeting(seed);
    const reward = options.hasCodeSuggestion || options.codeSnippet || options.mode8Actions?.length
      ? buildPersonalizedEmotionalReward({
          seed,
          task: options.task,
          codeSnippet: options.codeSnippet,
          mode8Actions: options.mode8Actions,
          hasCodeSuggestion: true,
          rewardSubject: options.rewardSubject,
        })
      : pickPositiveReinforcement(seed);
    const wellnessTip = selectDynamicWellnessTip(sessionMinutes, seed);
    const moodQuestion = pickSessionMoodQuestion(seed);
    return `${greeting}\n\n${reward}\n\n${wellnessTip}\n\n${moodQuestion}`;
  }

  // Extract fenced blocks to keep technical code 100% untouched
  const fencedBlocks: string[] = [];
  const placeholderText = original.replace(/```[\s\S]*?```/g, (block) => {
    const idx = fencedBlocks.length;
    fencedBlocks.push(block);
    return `__WXDIV_BLOCK_${idx}__`;
  });

  const prefix = getMissingWellbeingPrefix(original, {
    ...options,
    seed,
    sessionDurationMinutes: sessionMinutes,
  });
  const suffix = getMissingWellbeingSuffix(original, {
    ...options,
    seed,
    sessionDurationMinutes: sessionMinutes,
  });

  let prose = placeholderText.trim();
  if (prefix) {
    prose = prose ? `${prefix}\n\n${prose}` : prefix;
  }
  if (suffix) {
    prose = prose ? `${prose}\n\n${suffix}` : suffix;
  }

  // Re-insert technical fenced blocks without modifying their syntax
  return prose.replace(/__WXDIV_BLOCK_(\d+)__/g, (_m, idxStr) => {
    const idx = Number(idxStr);
    return fencedBlocks[idx] ?? "";
  });
}

/**
 * Client-side Copilot chat message interceptor:
 * Ensures every assistant message delivered to the chat stream passes through the wellbeing
 * & emotional-reward middleware while keeping codeSnippet and mode8Actions uncorrupted.
 */
export function interceptCopilotChatMessage(
  message: LlmChatMessage,
  userPromptSeed?: string,
  options?: {
    sessionDurationMinutes?: number;
    task?: string;
    rewardSubject?: string;
  }
): LlmChatMessage {
  if (message.role !== "assistant") {
    return message;
  }

  const sessionDurationMinutes =
    typeof options?.sessionDurationMinutes === "number"
      ? options.sessionDurationMinutes
      : getSessionDurationMinutes();

  const hasCode = Boolean(
    (message.codeSnippet && message.codeSnippet.trim().length > 0) ||
      (message.mode8Actions && message.mode8Actions.length > 0)
  );

  const seed = userPromptSeed || message.id || message.content;

  const enhancedContent = applyWellbeingResponseMiddleware(message.content, {
    seed,
    task: options?.task,
    preserveCodeBlocks: true,
    sessionDurationMinutes,
    codeSnippet: message.codeSnippet,
    mode8Actions: message.mode8Actions,
    hasCodeSuggestion: hasCode,
    rewardSubject: options?.rewardSubject,
  });

  const emotionalReward = hasCode
    ? buildPersonalizedEmotionalReward({
        seed,
        task: options?.task,
        codeSnippet: message.codeSnippet,
        mode8Actions: message.mode8Actions,
        hasCodeSuggestion: true,
        rewardSubject: options?.rewardSubject,
      })
    : undefined;

  return {
    ...message,
    content: enhancedContent,
    emotionalReward: message.emotionalReward || emotionalReward,
  };
}
